import { NextRequest } from "next/server";
import { getSessionId } from "@/app/lib/identity";
import { getVisitor, logEvent, toPublic } from "@/app/lib/presence";

export const dynamic = "force-dynamic";

/**
 * A wave is the one social primitive here: it writes a line into the shared
 * activity feed so the other person sees it on their own globe.
 */
export async function POST(request: NextRequest) {
  const sessionId = await getSessionId();
  if (!sessionId) {
    return Response.json({ error: "No session cookie — reload the page." }, { status: 428 });
  }

  let targetId: string;
  try {
    ({ targetId } = (await request.json()) as { targetId: string });
  } catch {
    return Response.json({ error: "Invalid JSON body." }, { status: 400 });
  }

  const [me, them] = await Promise.all([getVisitor(sessionId), getVisitor(targetId)]);
  if (!me) return Response.json({ error: "You're not on the globe yet." }, { status: 409 });
  if (!them) return Response.json({ error: "That visitor has left." }, { status: 404 });
  if (me.id === them.id) {
    return Response.json({ error: "You can't wave at yourself." }, { status: 400 });
  }

  const mePublic = toPublic(me, sessionId);
  await logEvent({
    visitorId: me.id,
    alias: me.alias,
    kind: "wave",
    detail: them.alias,
    countryCode: mePublic.countryCode,
    countryName: mePublic.countryName,
  });

  return Response.json({ ok: true });
}

import { NextRequest } from "next/server";
import { getClientIp, getSessionId, getUserAgent } from "@/app/lib/identity";
import { lookupIp, moduleStatus } from "@/app/lib/ipstackLookup";
import {
  getVisitor,
  listActivity,
  listLive,
  logEvent,
  sweep,
  toPublic,
  upsertVisitor,
} from "@/app/lib/presence";
import type { PresencePayload } from "@/interfaces/visitor.interface";

export const dynamic = "force-dynamic";

/** Re-geolocate at most this often per session — heartbeats are far cheaper. */
const GEO_REFRESH_MS = 10 * 60_000;

/**
 * The single endpoint the globe polls: it heartbeats the caller, then returns
 * everyone currently live plus the recent activity feed.
 */
export async function GET(request: NextRequest) {
  const sessionId = await getSessionId();
  if (!sessionId) {
    return Response.json(
      { error: "No session cookie yet — reload the page." },
      { status: 428 }
    );
  }

  const ip = (await getClientIp()) ?? "";
  const userAgent = await getUserAgent();

  let existing;
  try {
    existing = await getVisitor(sessionId);
  } catch (e) {
    return Response.json(
      { error: `Database unavailable: ${e instanceof Error ? e.message : String(e)}` },
      { status: 500 }
    );
  }

  // Only hit ipstack on first sight, when the snapshot has gone stale, or when
  // a previous attempt left us without coordinates to plot.
  const needsGeo =
    !existing?.ipstackJson ||
    existing.lat === 0 ||
    Date.now() - existing.joinedAt > GEO_REFRESH_MS ||
    request.nextUrl.searchParams.get("refresh") === "1";

  let apiMeta: PresencePayload["apiMeta"] = {
    maskedUrl: null,
    elapsedMs: null,
    status: null,
    cached: false,
    modules: moduleStatus(),
    notice: null,
  };
  let geo = null;

  if (needsGeo) {
    const outcome = await lookupIp(ip || null);
    apiMeta = {
      maskedUrl: outcome.maskedUrl || null,
      elapsedMs: outcome.elapsedMs || null,
      status: outcome.status || null,
      cached: outcome.cached,
      modules: moduleStatus(),
      notice: outcome.notice,
    };
    // A failed lookup is a notice, never a hard error: everyone else on the
    // globe should keep rendering regardless of one caller's bad luck.
    if (!outcome.notice) geo = outcome.body;
  }

  const { row, created } = await upsertVisitor({
    id: sessionId,
    ip: ip || "0.0.0.0",
    geo,
    userAgent,
  });

  if (created) {
    await logEvent({
      visitorId: row.id,
      alias: row.alias,
      kind: "joined",
      detail: geo?.city ?? null,
      countryCode: geo?.country_code ?? null,
      countryName: geo?.country_name ?? null,
    });
    // Opportunistic housekeeping, only on the rare "someone new" path.
    sweep().catch(() => {});
  }

  const [live, activity] = await Promise.all([listLive(), listActivity()]);
  const visitorsPublic = live.map((v) => toPublic(v, sessionId));

  const payload: PresencePayload = {
    you: visitorsPublic.find((v) => v.isYou) ?? toPublic(row, sessionId),
    visitors: visitorsPublic,
    activity,
    serverTime: Date.now(),
    apiMeta,
  };

  return Response.json(payload, { headers: { "cache-control": "no-store" } });
}

import { NextRequest } from "next/server";
import { eq } from "drizzle-orm";
import { db } from "@/app/lib/db";
import { visitors } from "@/app/lib/db/schema";
import { getSessionId } from "@/app/lib/identity";
import { ensureSchema, getVisitor, logEvent, toPublic } from "@/app/lib/presence";
import type { ProfileInput } from "@/interfaces/visitor.interface";

export const dynamic = "force-dynamic";

const LIMITS = {
  displayName: 40,
  headline: 80,
  bio: 600,
  lookingFor: 300,
  email: 120,
  website: 160,
  social: 120,
  tags: 160,
} as const;

const clean = (v: unknown, max: number): string | null => {
  if (typeof v !== "string") return null;
  const s = v.replace(/\s+/g, " ").trim().slice(0, max);
  return s.length ? s : null;
};

/** Normalise a URL so a bare "example.com" still renders as a safe link. */
const cleanUrl = (v: unknown): string | null => {
  const s = clean(v, LIMITS.website);
  if (!s) return null;
  const withScheme = /^https?:\/\//i.test(s) ? s : `https://${s}`;
  try {
    const u = new URL(withScheme);
    return u.protocol === "http:" || u.protocol === "https:" ? u.toString() : null;
  } catch {
    return null;
  }
};

const cleanTags = (v: unknown): string | null => {
  const s = clean(v, LIMITS.tags);
  if (!s) return null;
  const list = s
    .split(/[,\s]+/)
    .map((t) => t.replace(/^#/, "").toLowerCase().replace(/[^a-z0-9+.-]/g, ""))
    .filter(Boolean)
    .slice(0, 8);
  return list.length ? [...new Set(list)].join(",") : null;
};

export async function PUT(request: NextRequest) {
  const sessionId = await getSessionId();
  if (!sessionId) {
    return Response.json({ error: "No session cookie — reload the page." }, { status: 428 });
  }

  await ensureSchema();
  const existing = await getVisitor(sessionId);
  if (!existing) {
    return Response.json(
      { error: "You're not on the globe yet — wait for the first ping." },
      { status: 409 }
    );
  }

  let body: ProfileInput;
  try {
    body = (await request.json()) as ProfileInput;
  } catch {
    return Response.json({ error: "Invalid JSON body." }, { status: 400 });
  }

  const email = clean(body.email, LIMITS.email);
  if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
    return Response.json({ error: `"${email}" is not a valid email address.` }, { status: 400 });
  }

  const patch = {
    displayName: clean(body.displayName, LIMITS.displayName),
    headline: clean(body.headline, LIMITS.headline),
    bio: clean(body.bio, LIMITS.bio),
    lookingFor: clean(body.lookingFor, LIMITS.lookingFor),
    email,
    website: cleanUrl(body.website),
    social: clean(body.social, LIMITS.social),
    tags: cleanTags(body.tags),
    lastSeenAt: Date.now(),
  };

  await db.update(visitors).set(patch).where(eq(visitors.id, sessionId));

  const wasBlank = !(
    existing.displayName ||
    existing.headline ||
    existing.bio ||
    existing.lookingFor ||
    existing.tags
  );
  const nowFilled = Boolean(
    patch.displayName || patch.headline || patch.bio || patch.lookingFor || patch.tags
  );
  if (nowFilled) {
    const updated = toPublic({ ...existing, ...patch }, sessionId);
    await logEvent({
      visitorId: sessionId,
      alias: existing.alias,
      kind: wasBlank ? "profile" : "profile_update",
      detail: patch.headline ?? patch.displayName ?? null,
      countryCode: updated.countryCode,
      countryName: updated.countryName,
    });
  }

  return Response.json({ you: toPublic({ ...existing, ...patch }, sessionId) });
}

/**
 * Tile fetching with three layers of caching in front of the network:
 *
 *  1. An in-flight map, so a tile requested twice in the same frame — which
 *     happens constantly as the view and its parent zoom overlap — is fetched
 *     once.
 *  2. The Cache Storage API, so tiles survive a reload and a cold start costs
 *     nothing on a route somebody has already flown.
 *  3. The caller's own texture cache, keyed by URL.
 *
 * Decoding goes through `createImageBitmap`, which happens off the main thread;
 * `TextureLoader`'s `<img>` path decodes on it and shows up as jank at exactly
 * the moment forty tiles land at once.
 */

const CACHE_NAME = "collabfab-tiles-v1";

const inFlight = new Map<string, Promise<ImageBitmap | null>>();

/** Cache Storage needs a secure context; plain http:// silently has no `caches`. */
const cacheStorageAvailable = () =>
  typeof caches !== "undefined" && typeof window !== "undefined" && window.isSecureContext;

async function fetchBitmap(url: string): Promise<ImageBitmap | null> {
  let response: Response | undefined;

  if (cacheStorageAvailable()) {
    try {
      const cache = await caches.open(CACHE_NAME);
      response = await cache.match(url);
      if (!response) {
        response = await fetch(url, { mode: "cors" });
        // Store a clone; the original is consumed below.
        if (response.ok) void cache.put(url, response.clone()).catch(() => {});
      }
    } catch {
      response = undefined;
    }
  }

  if (!response) {
    try {
      response = await fetch(url, { mode: "cors" });
    } catch {
      return null;
    }
  }

  if (!response.ok) return null;
  try {
    // Flip at decode time rather than at upload time: WebGL's UNPACK_FLIP_Y
    // is unreliable for ImageBitmap sources, and doing it here keeps the work
    // off the main thread. Textures built from these must set flipY = false.
    return await createImageBitmap(await response.blob(), {
      imageOrientation: "flipY",
    });
  } catch {
    return null;
  }
}

/** Resolves to null for a tile that genuinely isn't there — oceans at deep zoom. */
export function loadTileBitmap(url: string): Promise<ImageBitmap | null> {
  const existing = inFlight.get(url);
  if (existing) return existing;

  const pending = fetchBitmap(url)
    .catch(() => null)
    .finally(() => inFlight.delete(url));

  inFlight.set(url, pending);
  return pending;
}

/** Drop the persistent tile cache — used when the basemap source changes. */
export async function clearTileCache() {
  if (!cacheStorageAvailable()) return;
  try {
    await caches.delete(CACHE_NAME);
  } catch {
    /* nothing to clean up */
  }
}

import { NextResponse, type NextRequest } from "next/server";

// Next.js 16 renamed Middleware to Proxy. This runs before every request and
// mints a *session* cookie (no maxAge/expires) so a visitor's identity and
// profile live only as long as the browser stays open — close it or clear
// cookies and they return as a brand-new stranger on the globe.
export function proxy(request: NextRequest) {
  const res = NextResponse.next();
  if (!request.cookies.get("collabfab_sid")) {
    res.cookies.set("collabfab_sid", crypto.randomUUID(), {
      httpOnly: true,
      sameSite: "lax",
      path: "/",
    });
  }
  return res;
}

