  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(faqJsonLd) }}
      />
      <Stage />
    </>
  );
}

export type VisitorLanguage = { code?: string; name?: string; native?: string };

/** What every client on the globe is allowed to see about a visitor. */
export type PublicVisitor = {
  id: string;
  alias: string;
  isYou: boolean;
  joinedAt: number;
  lastSeenAt: number;

  // Location (ipstack)
  lat: number | null;
  lon: number | null;
  city: string | null;
  regionName: string | null;
  countryCode: string | null;
  countryName: string | null;
  countryFlag: string | null;
  continentCode: string | null;
  continentName: string | null;
  zip: string | null;
  isEu: boolean | null;
  capital: string | null;
  callingCode: string | null;

  // Time & locale (ipstack)
  timezoneId: string | null;
  gmtOffset: number | null; // seconds
  /** Where gmtOffset came from — ipstack's module, or estimated from longitude. */
  tzSource: "ipstack" | "estimated" | "unknown";
  isDst: boolean | null;
  languages: VisitorLanguage[];
  currencyCode: string | null;
  currencyName: string | null;
  currencySymbol: string | null;

  // Network (ipstack connection + security)
  ipMasked: string | null;
  ipType: string | null;
  hostname: string | null;
  asn: number | null;
  isp: string | null;
  /** True when `isp` was derived from reverse DNS rather than ipstack's module. */
  ispFromDns: boolean;
  connectionType: string | null;
  routingType: string | null;
  organizationType: string | null;
  isHosting: boolean | null;
  isProxy: boolean | null;
  proxyType: string | null;
  isTor: boolean | null;
  isCrawler: boolean | null;
  threatLevel: string | null;
  vpnService: string | null;

  // Client
  os: string | null;
  browser: string | null;
  device: string | null;

  // Self-declared profile (session-scoped, vanishes with the cookie)
  displayName: string | null;
  headline: string | null;
  bio: string | null;
  lookingFor: string | null;
  email: string | null;
  website: string | null;
  social: string | null;
  tags: string[];
  hasProfile: boolean;

  /** True only for the clearly-labelled simulated crowd, never for real people. */
  isDemo?: boolean;
};

export type ActivityItem = {
  id: string;
  visitorId: string;
  alias: string;
  kind: string;
  detail: string | null;
  countryCode: string | null;
  countryName: string | null;
  createdAt: number;
};

export type PresencePayload = {
  you: PublicVisitor | null;
  visitors: PublicVisitor[];
  activity: ActivityItem[];
  serverTime: number;
  apiMeta: {
    maskedUrl: string | null;
    elapsedMs: number | null;
    status: number | null;
    cached: boolean;
    /** Optional ipstack modules this access key turned out to be entitled to. */
    modules: { hostname: boolean; security: boolean };
    /** Non-fatal explanation when the caller's own lookup didn't work out. */
    notice: string | null;
  };
};

export type ProfileInput = {
  displayName?: string;
  headline?: string;
  bio?: string;
  lookingFor?: string;
  email?: string;
  website?: string;
  social?: string;
  tags?: string;
};

// Tiny deterministic hash (FNV-1a, 32-bit) so an id always renders the same
// alias, avatar and colour on every client without storing any of it.
export function hash32(input: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < input.length; i++) {
    h ^= input.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

// Deterministic PRNG stream seeded from a string.
export function seeded(input: string) {
  let s = hash32(input) || 1;
  return () => {
    s ^= s << 13;
    s >>>= 0;
    s ^= s >> 17;
    s ^= s << 5;
    s >>>= 0;
    return s / 0x100000000;
  };
}

export function pick<T>(list: readonly T[], rnd: () => number): T {
  return list[Math.floor(rnd() * list.length) % list.length];
}

"use client";

import { useMemo } from "react";
import { accentFor, avatarSvg } from "@/app/lib/avatar";

export function Avatar({
  seed,
  size = 40,
  ring,
  className = "",
}: {
  seed: string;
  size?: number;
  ring?: string;
  className?: string;
}) {
  const svg = useMemo(() => avatarSvg(seed, size), [seed, size]);
  return (
    <span
      className={`inline-block shrink-0 overflow-hidden rounded-full ${className}`}
      style={{
        width: size,
        height: size,
        boxShadow: ring ? `0 0 0 2px ${ring}` : undefined,
        background: "#1a1c2b",
      }}
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  );
}

export { accentFor };

import { cookies, headers } from "next/headers";

export const SESSION_COOKIE = "collabfab_sid";

export async function getSessionId(): Promise<string | null> {
  const c = await cookies();
  return c.get(SESSION_COOKIE)?.value ?? null;
}

export async function requireSessionId(): Promise<string> {
  const v = await getSessionId();
  if (!v) {
    throw new Error(
      `${SESSION_COOKIE} cookie missing — proxy.ts should have set it. Hard-refresh the page.`
    );
  }
  return v;
}

export async function getClientIp(): Promise<string | null> {
  const h = await headers();
  const xff = h.get("x-forwarded-for");
  if (xff) {
    const first = xff.split(",")[0]?.trim();
    if (first) return first;
  }
  return h.get("x-real-ip");
}

export async function getUserAgent(): Promise<string | null> {
  return (await headers()).get("user-agent");
}
